126	pub(super) struct Registry {
127	    thread_infos: Vec<ThreadInfo>,
128	    sleep: Sleep,
129	    injected_jobs: Injector<JobRef>,
130	    broadcasts: Mutex<Vec<Worker<JobRef>>>,
131	    panic_handler: Option<Box<PanicHandler>>,
132	    start_handler: Option<Box<StartHandler>>,
133	    exit_handler: Option<Box<ExitHandler>>,
134	
135	    // When this latch reaches 0, it means that all work on this
136	    // registry must be complete. This is ensured in the following ways:
137	    //
138	    // - if this is the global registry, there is a ref-count that never
139	    //   gets released.
140	    // - if this is a user-created thread pool, then so long as the thread pool
141	    //   exists, it holds a reference.
142	    // - when we inject a "blocking job" into the registry with `ThreadPool::install()`,
143	    //   no adjustment is needed; the `ThreadPool` holds the reference, and since we won't
144	    //   return until the blocking job is complete, that ref will continue to be held.
145	    // - when `join()` or `scope()` is invoked, similarly, no adjustments are needed.
146	    //   These are always owned by some other job (e.g., one injected by `ThreadPool::install()`)
147	    //   and that job will keep the pool alive.
148	    terminate_count: AtomicUsize,
149	}
