236	impl Registry {
237	    pub(super) fn new<S>(
238	        mut builder: ThreadPoolBuilder<S>,
239	    ) -> Result<Arc<Self>, ThreadPoolBuildError>
240	    where
241	        S: ThreadSpawn,
242	    {
243	        // Soft-limit the number of threads that we can actually support.
244	        let n_threads = Ord::min(builder.get_num_threads(), crate::max_num_threads());
245	
246	        let breadth_first = builder.get_breadth_first();
247	
248	        let (workers, stealers): (Vec<_>, Vec<_>) = (0..n_threads)
249	            .map(|_| {
250	                let worker = if breadth_first {
251	                    Worker::new_fifo()
252	                } else {
253	                    Worker::new_lifo()
254	                };
255	
256	                let stealer = worker.stealer();
257	                (worker, stealer)
258	            })
259	            .unzip();
260	
261	        let (broadcasts, broadcast_stealers): (Vec<_>, Vec<_>) = (0..n_threads)
262	            .map(|_| {
263	                let worker = Worker::new_fifo();
264	                let stealer = worker.stealer();
265	                (worker, stealer)
266	            })
267	            .unzip();
268	
269	        let registry = Arc::new(Registry {
270	            thread_infos: stealers.into_iter().map(ThreadInfo::new).collect(),
271	            sleep: Sleep::new(n_threads),
272	            injected_jobs: Injector::new(),
273	            broadcasts: Mutex::new(broadcasts),
274	            terminate_count: AtomicUsize::new(1),
275	            panic_handler: builder.take_panic_handler(),
276	            start_handler: builder.take_start_handler(),
277	            exit_handler: builder.take_exit_handler(),
278	        });
279	
280	        // If we return early or panic, make sure to terminate existing threads.
281	        let t1000 = Terminator(&registry);
282	
283	        for (index, (worker, stealer)) in workers.into_iter().zip(broadcast_stealers).enumerate() {
284	            let thread = ThreadBuilder {
285	                name: builder.get_thread_name(index),
286	                stack_size: builder.get_stack_size(),
287	                registry: Arc::clone(&registry),
288	                worker,
289	                stealer,
290	                index,
291	            };
292	
293	            if index == 0 && builder.use_current_thread {
294	                if !WorkerThread::current().is_null() {
295	                    return Err(ThreadPoolBuildError::new(
296	                        ErrorKind::CurrentThreadAlreadyInPool,
297	                    ));
298	                }
299	                // Rather than starting a new thread, we're just taking over the current thread
300	                // *without* running the main loop, so we can still return from here.
301	                // The WorkerThread is leaked, but we never shutdown the global pool anyway.
302	                let worker_thread = Box::into_raw(Box::new(WorkerThread::from(thread)));
303	
304	                unsafe {
305	                    WorkerThread::set_current(worker_thread);
306	                    Latch::set(&registry.thread_infos[index].primed);
307	                }
308	                continue;
309	            }
310	
311	            if let Err(e) = builder.get_spawn_handler().spawn(thread) {
312	                return Err(ThreadPoolBuildError::new(ErrorKind::IOError(e)));
313	            }
314	        }
315	
316	        // Returning normally now, without termination.
317	        mem::forget(t1000);
318	
319	        Ok(registry)
320	    }
