602	    /// Notify the worker that the latch they are sleeping on has been "set".
603	    pub(super) fn notify_worker_latch_is_set(&self, target_worker_index: usize) {
604	        self.sleep.notify_worker_latch_is_set(target_worker_index);
605	    }
606	}
