612	
613	struct ThreadInfo {
614	    /// Latch set once thread has started and we are entering into the
615	    /// main loop. Used to wait for worker threads to become primed,
616	    /// primarily of interest for benchmarking.
617	    primed: LockLatch,
618	
619	    /// Latch is set once worker thread has completed. Used to wait
620	    /// until workers have stopped; only used for tests.
621	    stopped: LockLatch,
622	
623	    /// The latch used to signal that terminated has been requested.
624	    /// This latch is *set* by the `terminate` method on the
625	    /// `Registry`, once the registry's main "terminate" counter
626	    /// reaches zero.
627	    terminate: OnceLatch,
628	
629	    /// the "stealer" half of the worker's deque
630	    stealer: Stealer<JobRef>,
631	}
632	
633	impl ThreadInfo {
634	    fn new(stealer: Stealer<JobRef>) -> ThreadInfo {
635	        ThreadInfo {
636	            primed: LockLatch::new(),
637	            stopped: LockLatch::new(),
638	            terminate: OnceLatch::new(),
639	            stealer,
640	        }
641	    }
642	}
643	
644	// ////////////////////////////////////////////////////////////////////////
645	// WorkerThread identifiers
646	
647	pub(super) struct WorkerThread {
648	    /// the "worker" half of our local deque
649	    worker: Worker<JobRef>,
650	
651	    /// the "stealer" half of the worker's broadcast deque
652	    stealer: Stealer<JobRef>,
653	
654	    /// local queue used for `spawn_fifo` indirection
655	    fifo: JobFifo,
656	
657	    index: usize,
658	
659	    /// A weak random number generator.
660	    rng: XorShift64Star,
661	
662	    registry: Arc<Registry>,
663	}
664	
665	// This is a bit sketchy, but basically: the WorkerThread is
666	// allocated on the stack of the worker on entry and stored into this
667	// thread-local variable. So it will remain valid at least until the
668	// worker is fully unwound. Using an unsafe pointer avoids the need
669	// for a RefCell<T> etc.
670	thread_local! {
671	    static WORKER_THREAD_STATE: Cell<*const WorkerThread> = const { Cell::new(ptr::null()) };
672	}
673	
674	impl From<ThreadBuilder> for WorkerThread {
675	    fn from(thread: ThreadBuilder) -> Self {
676	        Self {
677	            worker: thread.worker,
678	            stealer: thread.stealer,
679	            fifo: JobFifo::new(),
680	            index: thread.index,
681	            rng: XorShift64Star::new(),
682	            registry: thread.registry,
683	        }
684	    }
685	}
686	
687	impl Drop for WorkerThread {
688	    fn drop(&mut self) {
689	        // Undo `set_current`
690	        WORKER_THREAD_STATE.with(|t| {
691	            assert!(t.get().eq(&(self as *const _)));
692	            t.set(ptr::null());
693	        });
694	    }
695	}
696	
697	impl WorkerThread {
698	    /// Gets the `WorkerThread` index for the current thread; returns
699	    /// NULL if this is not a worker thread. This pointer is valid
700	    /// anywhere on the current thread.
701	    #[inline]
702	    pub(super) fn current() -> *const WorkerThread {
703	        WORKER_THREAD_STATE.get()
704	    }
705	
706	    /// Sets `self` as the worker-thread index for the current thread.
707	    /// This is done during worker-thread startup.
708	    unsafe fn set_current(thread: *const WorkerThread) {
709	        WORKER_THREAD_STATE.with(|t| {
710	            assert!(t.get().is_null());
711	            t.set(thread);
712	        });
713	    }
714	
715	    /// Returns the registry that owns this worker thread.
716	    #[inline]
717	    pub(super) fn registry(&self) -> &Arc<Registry> {
718	        &self.registry
719	    }
720	
721	    /// Our index amongst the worker threads (ranges from `0..self.num_threads()`).
722	    #[inline]
723	    pub(super) fn index(&self) -> usize {
724	        self.index
725	    }
726	
727	    #[inline]
728	    pub(super) unsafe fn push(&self, job: JobRef) {
729	        let queue_was_empty = self.worker.is_empty();
730	        self.worker.push(job);
731	        self.registry.sleep.new_internal_jobs(1, queue_was_empty);
732	    }
733	
734	    #[inline]
735	    pub(super) unsafe fn push_fifo(&self, job: JobRef) {
736	        unsafe { self.push(self.fifo.push(job)) };
737	    }
738	
739	    #[inline]
740	    pub(super) fn local_deque_is_empty(&self) -> bool {
741	        self.worker.is_empty()
742	    }
743	
744	    /// Attempts to obtain a "local" job -- typically this means
745	    /// popping from the top of the stack, though if we are configured
746	    /// for breadth-first execution, it would mean dequeuing from the
747	    /// bottom.
748	    #[inline]
749	    pub(super) fn take_local_job(&self) -> Option<JobRef> {
750	        let popped_job = self.worker.pop();
751	
752	        if popped_job.is_some() {
753	            return popped_job;
754	        }
755	
756	        loop {
757	            match self.stealer.steal() {
758	                Steal::Success(job) => return Some(job),
759	                Steal::Empty => return None,
760	                Steal::Retry => std::hint::spin_loop(),
761	            }
762	        }
763	    }
764	
765	    fn has_injected_job(&self) -> bool {
766	        !self.stealer.is_empty() || self.registry.has_injected_job()
767	    }
768	
769	    /// Wait until the latch is set. Try to keep busy by popping and
770	    /// stealing tasks as necessary.
771	    #[inline]
772	    pub(super) unsafe fn wait_until<L: AsCoreLatch + ?Sized>(&self, latch: &L) {
773	        let latch = latch.as_core_latch();
774	        if !latch.probe() {
775	            unsafe { self.wait_until_cold(latch) };
776	        }
777	    }
778	
779	    #[cold]
780	    unsafe fn wait_until_cold(&self, latch: &CoreLatch) {
781	        // the code below should swallow all panics and hence never
782	        // unwind; but if something does wrong, we want to abort,
783	        // because otherwise other code in rayon may assume that the
784	        // latch has been signaled, and that can lead to random memory
785	        // accesses, which would be *very bad*
786	        let abort_guard = unwind::AbortIfPanic;
787	
788	        'outer: while !latch.probe() {
789	            // Check for local work *before* we start marking ourself idle,
790	            // especially to avoid modifying shared sleep state.
791	            if let Some(job) = self.take_local_job() {
792	                unsafe { self.execute(job) };
793	                continue;
794	            }
795	
796	            let mut idle_state = self.registry.sleep.start_looking(self.index);
797	            while !latch.probe() {
798	                if let Some(job) = self.find_work() {
799	                    self.registry.sleep.work_found();
800	                    unsafe { self.execute(job) };
801	                    // The job might have injected local work, so go back to the outer loop.
802	                    continue 'outer;
803	                } else {
804	                    self.registry
805	                        .sleep
806	                        .no_work_found(&mut idle_state, latch, || self.has_injected_job())
807	                }
808	            }
809	
810	            // If we were sleepy, we are not anymore. We "found work" --
811	            // whatever the surrounding thread was doing before it had to wait.
812	            self.registry.sleep.work_found();
813	            break;
814	        }
815	
816	        mem::forget(abort_guard); // successful execution, do not abort
817	    }
818	
819	    unsafe fn wait_until_out_of_work(&self) {
820	        unsafe {
821	            debug_assert_eq!(self as *const _, WorkerThread::current());
822	            let registry = &*self.registry;
823	            let index = self.index;
824	
825	            self.wait_until(&registry.thread_infos[index].terminate);
826	
827	            // Should not be any work left in our queue.
828	            debug_assert!(self.take_local_job().is_none());
829	
830	            // Let registry know we are done
831	            Latch::set(&registry.thread_infos[index].stopped);
832	        }
833	    }
834	
835	    fn find_work(&self) -> Option<JobRef> {
836	        // Try to find some work to do. We give preference first
837	        // to things in our local deque, then in other workers
838	        // deques, and finally to injected jobs from the
839	        // outside. The idea is to finish what we started before
840	        // we take on something new.
841	        self.take_local_job()
842	            .or_else(|| self.steal())
843	            .or_else(|| self.registry.pop_injected_job())
844	    }
845	
846	    pub(super) fn yield_now(&self) -> Yield {
847	        match self.find_work() {
848	            Some(job) => unsafe {
849	                self.execute(job);
850	                Yield::Executed
851	            },
852	            None => Yield::Idle,
853	        }
854	    }
855	
856	    pub(super) fn yield_local(&self) -> Yield {
857	        match self.take_local_job() {
858	            Some(job) => unsafe {
859	                self.execute(job);
860	                Yield::Executed
861	            },
862	            None => Yield::Idle,
863	        }
864	    }
865	
866	    #[inline]
867	    pub(super) unsafe fn execute(&self, job: JobRef) {
868	        unsafe { job.execute() };
869	    }
870	
871	    /// Try to steal a single job and return it.
872	    ///
873	    /// This should only be done as a last resort, when there is no
874	    /// local work to do.
875	    fn steal(&self) -> Option<JobRef> {
876	        // we only steal when we don't have any work to do locally
877	        debug_assert!(self.local_deque_is_empty());
878	
879	        // otherwise, try to steal
880	        let thread_infos = &self.registry.thread_infos.as_slice();
881	        let num_threads = thread_infos.len();
882	        if num_threads <= 1 {
883	            return None;
884	        }
885	
886	        loop {
887	            let mut retry = false;
888	            let start = self.rng.next_usize(num_threads);
889	            let job = (start..num_threads)
890	                .chain(0..start)
891	                .filter(move |&i| i != self.index)
892	                .find_map(|victim_index| {
893	                    let victim = &thread_infos[victim_index];
894	                    match victim.stealer.steal() {
895	                        Steal::Success(job) => Some(job),
896	                        Steal::Empty => None,
897	                        Steal::Retry => {
898	                            retry = true;
899	                            None
900	                        }
901	                    }
902	                });
903	            if job.is_some() || !retry {
904	                return job;
905	            }
906	            std::hint::spin_loop();
907	        }
908	    }
909	}
910	
911	// ////////////////////////////////////////////////////////////////////////
912	
913	unsafe fn main_loop(thread: ThreadBuilder) {
914	    unsafe {
915	        let worker_thread = &WorkerThread::from(thread);
916	        WorkerThread::set_current(worker_thread);
917	        let registry = &*worker_thread.registry;
918	        let index = worker_thread.index;
919	
920	        // let registry know we are ready to do work
921	        Latch::set(&registry.thread_infos[index].primed);
922	
923	        // Worker threads should not panic. If they do, just abort, as the
924	        // internal state of the thread pool is corrupted. Note that if
925	        // **user code** panics, we should catch that and redirect.
926	        let abort_guard = unwind::AbortIfPanic;
927	
928	        // Inform a user callback that we started a thread.
929	        if let Some(ref handler) = registry.start_handler {
930	            registry.catch_unwind(|| handler(index));
931	        }
932	
933	        worker_thread.wait_until_out_of_work();
934	
935	        // Normal termination, do not abort.
936	        mem::forget(abort_guard);
937	
938	        // Inform a user callback that we exited a thread.
939	        if let Some(ref handler) = registry.exit_handler {
940	            registry.catch_unwind(|| handler(index));
941	            // We're already exiting the thread, there's nothing else to do.
942	        }
943	    }
944	}
945	
946	/// If already in a worker-thread, just execute `op`.  Otherwise,
947	/// execute `op` in the default thread pool. Either way, block until
948	/// `op` completes and return its return value. If `op` panics, that
949	/// panic will be propagated as well.  The second argument indicates
950	/// `true` if injection was performed, `false` if executed directly.
951	pub(super) fn in_worker<OP, R>(op: OP) -> R
952	where
953	    OP: FnOnce(&WorkerThread, bool) -> R + Send,
954	    R: Send,
955	{
956	    unsafe {
957	        let owner_thread = WorkerThread::current();
958	        if !owner_thread.is_null() {
959	            // Perfectly valid to give them a `&T`: this is the
960	            // current thread, so we know the data structure won't be
961	            // invalidated until we return.
962	            op(&*owner_thread, false)
963	        } else {
964	            global_registry().in_worker(op)
965	        }
966	    }
967	}
968	
969	/// [xorshift*] is a fast pseudorandom number generator which will
970	/// even tolerate weak seeding, as long as it's not zero.
971	///
972	/// [xorshift*]: https://en.wikipedia.org/wiki/Xorshift#xorshift*
973	struct XorShift64Star {
974	    state: Cell<u64>,
975	}
976	
977	impl XorShift64Star {
978	    fn new() -> Self {
979	        // Any non-zero seed will do -- this uses the hash of a global counter.
980	        let mut seed = 0;
981	        while seed == 0 {
982	            let mut hasher = DefaultHasher::new();
983	            static COUNTER: AtomicUsize = AtomicUsize::new(0);
984	            hasher.write_usize(COUNTER.fetch_add(1, Ordering::Relaxed));
985	            seed = hasher.finish();
986	        }
987	
988	        XorShift64Star {
989	            state: Cell::new(seed),
990	        }
991	    }
992	
993	    fn next(&self) -> u64 {
994	        let mut x = self.state.get();
995	        debug_assert_ne!(x, 0);
996	        x ^= x >> 12;
997	        x ^= x << 25;
998	        x ^= x >> 27;
999	        self.state.set(x);
1000	        x.wrapping_mul(0x2545_f491_4f6c_dd1d)
1001	    }
1002	
1003	    /// Return a value from `0..n`.
1004	    fn next_usize(&self, n: usize) -> usize {
1005	        (self.next() % n as u64) as usize
1006	    }
1007	}
